class Simulation:
    ...
    def run(self) -> dict:
        for _ in range(self.T):
            self.step()
            if self._early_stop():
                break
        return self.results()

    def step(self) -> None:
        mandate = self.policy.issue_mask_mandate(self.day)
        policy_signal = 1.0 if mandate else 0.0
        campaign = self.policy.run_information_campaign(self.day)
        media_base = self.media_channel.broadcast_message()
        net_media = clamp01(media_base + 0.5 * policy_signal * campaign) - clamp01(self.misinformation_rate * (1.0 - self.message_credibility))
        for p in self.people:
            p.update_from_media(net_media)
        adopt_prev = [1 if p.is_wearing_mask else 0 for p in self.people]
        peer_rate = [self.peer_share(i, adopt_prev) for i in range(self.n)]
        attempted = 0
        sold_today = 0
        fines_today = 0.0
        for i, agent in enumerate(self.people):
            willing = agent.decide_willingness(peer_rate[i], policy_signal, self.vendor.price, self.weights, self.enforcement_strength, self.fine_amount, self.rng, self.subsidy_level, self.wealth_effect_on_adoption)
            if willing and agent.mask_inventory <= 0:
                attempted += 1
                units = self.vendor.sell(1, agent.budget, self.subsidy_level)
                if units > 0:
                    sold_today += units
                    agent.budget = max(0.0, agent.budget - self.vendor.effective_price(self.subsidy_level) * units)
                    agent.mask_inventory += units
            agent.is_wearing_mask = willing and agent.mask_inventory > 0
            if agent.is_wearing_mask:
                agent.mask_inventory -= 1
            if mandate and not agent.is_wearing_mask:
                if self.rng.random() < self.enforcement_check_probability * self.enforcement_strength:
                    fines_today += self.fine_amount
            agent.update_habit_and_fatigue(self.habit_formation_rate, self.habit_decay_rate, self.fatigue_change_wear, self.fatigue_recovery)
        self.metrics["masks_sold_daily"].append(sold_today)
        self.metrics["masks_sold_cum"] += sold_today
        self.metrics["fines_collected_cum"] += fines_today
        if self.vendor.inventory <= 0:
            self.metrics["stockout_steps"] += 1
        self.vendor.restock()
        self.metrics["masks_restocked_cum"] += self.vendor.restock_per_day
        self.vendor.adjust_price(self.target_inventory)
        if self.disease_enabled:
            self._disease_step()
        adoption_today = sum(1 for p in self.people if p.is_wearing_mask) / max(1, self.n)
        self.metrics["adoption_rate_over_time"].append(clamp01(adoption_today))
        self.metrics["mandate_active_ts"].append(mandate)
        self.day += 1
        self._validate_step()

    def _disease_step(self) -> None:
        new_exposed = []
        infectious_ids = [i for i, s in enumerate(self.health_states) if s == 'I']
        for src in infectious_ids:
            contacts = self.rng.sample(self.people[src].neighbors, k=min(len(self.people[src].neighbors), max(1, int(self.contacts_comm))))
            for tgt in contacts:
                if self.health_states[tgt] != 'S':
                    continue
                p_base = self.base_transmission_prob
                if self.people[src].is_wearing_mask:
                    p_base *= (1.0 - self.mask_effectiveness_source)
                if self.people[tgt].is_wearing_mask:
                    p_base *= (1.0 - self.mask_effectiveness_wearer)
                if self.rng.random() < p_base:
                    new_exposed.append(tgt)
        for i in range(self.n):
            if self.health_states[i] == 'E':
                self.days_in_state[i] += 1
                if self.days_in_state[i] >= self.incubation_period:
                    self.health_states[i] = 'I'
                    self.days_in_state[i] = 0
                    self.is_symptomatic[i] = (self.rng.random() < self.symptomatic_fraction)
            elif self.health_states[i] == 'I':
                self.days_in_state[i] += 1
                if self.days_in_state[i] >= self.infectious_period:
                    self.health_states[i] = 'R'
                    self.days_in_state[i] = 0
        for idx in set(new_exposed):
            if self.health_states[idx] == 'S':
                self.health_states[idx] = 'E'
                self.days_in_state[idx] = 0
        self.metrics["infections_ts"].append(len(new_exposed))

    def results(self) -> dict:
        series = self.metrics["adoption_rate_over_time"]
        n_days = len(series)
        overall_avg = sum(series) / max(1, n_days)
        t50 = next((d for d, v in enumerate(series) if v >= 0.5), None)
        equity_gap = self._gini_by_income()
        supply_demand_ratio = (sum(self.metrics["masks_sold_daily"]) + self.vendor.inventory) / max(1, sum(self.metrics["masks_sold_daily"]) + self.metrics.get("demand_attempts", 0)) if self.metrics.get("demand_attempts") else 1.0
        cumulative_infections = sum(self.metrics.get("infections_ts", []))
        return {
            "overall_adoption_rate": overall_avg,
            "time_to_50_percent_adoption": t50,
            "equity_gap_in_adoption": equity_gap,
            "supply_demand_ratio": supply_demand_ratio,
            "cumulative_infections": cumulative_infections,
            "adoption_rate_over_time": series,
        }

    def _validate_step(self) -> None:
        if self.metrics["adoption_rate_over_time"]:
            self.metrics["adoption_rate_over_time"][-1] = clamp01(self.metrics["adoption_rate_over_time"][-1])
        self.vendor.inventory = max(0, self.vendor.inventory)

    def _early_stop(self) -> bool:
        s = self.metrics["adoption_rate_over_time"]
        if len(s) < 21:
            return False
        last = s[-14:]
        ma = sum(last) / len(last)
        prev = s[-21:-7]
        ma_prev = sum(prev) / len(prev)
        return abs(ma - ma_prev) < 0.005

    def peer_share(self, i: int, adopt_flags: list) -> float:
        neigh = self.neighbors[i]
        if not neigh:
            return sum(adopt_flags) / max(1, len(adopt_flags))
        return sum(adopt_flags[j] for j in neigh) / max(1, len(neigh))


