def sell(self, max_units: int, budget: float, subsidy_level: float) -> int:
    if self.inventory <= 0 or max_units <= 0:
        return 0
    eff_price = max(self.min_price, self.effective_price(subsidy_level))
    if eff_price <= 0:
        eff_price = self.min_price
    affordable_units = int(max(0.0, budget) // eff_price)
    units = min(max_units, self.inventory, affordable_units)
    self.inventory = max(0, self.inventory - units)
    return units

def generate_small_world(n: int, k: int, beta: float, rng: random.Random) -> List[List[int]]:
    if n <= 1:
        return [[] for _ in range(n)]
    neigh = [set() for _ in range(n)]
    half_k = max(1, k // 2)
    for i in range(n):
        for d in range(1, half_k + 1):
            j = (i + d) % n
            neigh[i].add(j); neigh[j].add(i)
            j2 = (i - d) % n
            neigh[i].add(j2); neigh[j2].add(i)
    for i in range(n):
        for j in list(neigh[i]):
            if j > i and rng.random() < beta:
                neigh[i].discard(j); neigh[j].discard(i)
                candidates = [x for x in range(n) if x != i and x not in neigh[i]]
                if candidates:
                    new_j = rng.choice(candidates)
                    neigh[i].add(new_j); neigh[new_j].add(i)
    return [sorted(lst) for lst in neigh]
